from datetime import datetime, timezone
from pathlib import Path

import ee
import geetools
from matplotlib import pyplot as plt
from vscee import Map

# prior to execute this code make sure you are authenticated
ee.Initialize(project="earthengine-extension")

initialization = ee.Date("2026-11-01T00:00:00Z")
france = ee.FeatureCollection("FAO/GAUL/2015/level0").filter(ee.Filter.eq("ADM0_NAME", "France"))
france_geometry = france.geometry()
forecasts = (
	ee.ImageCollection("NOAA/GFS0P25")
	.filterDate(initialization, initialization.advance(1, "day"))
	.filter(ee.Filter.eq("creation_time", initialization.millis()))
	.filter(ee.Filter.lte("forecast_hours", 120))
	.select("temperature_2m_above_ground")
	.map(lambda image: image.set("system:time_start", image.get("forecast_time")))
)
reducer = ee.Reducer.mean().combine(ee.Reducer.minMax(), sharedInputs=True)
daily = forecasts.geetools.reduceInterval(
	reducer=reducer,
	unit="day",
	duration=1,
	keep_original_names=False,
	count_images_per_interval=True,
).filterDate(initialization, initialization.advance(5, "day")).sort("system:time_start")
era5 = (
	ee.ImageCollection("ECMWF/ERA5_LAND/DAILY_AGGR")
	.filterDate(initialization, initialization.advance(5, "day"))
	.select("temperature_2m")
	.sort("system:time_start")
)
dates = daily.aggregate_array("system:time_start").getInfo()
counts = daily.aggregate_array("__geetools_generated_size__").getInfo()
era5_dates = era5.aggregate_array("system:time_start").getInfo()
if len(dates) != 5:
	raise RuntimeError(f"Expected five GFS days from 2026-11-01, found {len(dates)}")
if dates != era5_dates:
	raise RuntimeError("ERA5-Land daily dates do not match the GFS forecast dates")
if france.size().getInfo() == 0:
	raise RuntimeError("France was not found in FAO/GAUL/2015/level0")

print("Initialization: 2026-11-01 00 UTC")
print("Daily bands:", ee.Image(daily.first()).bandNames().getInfo())
print("Matched GFS / ERA5-Land days:", len(dates))
Map.clear()
vis_params = {
	"bands": ["average_temperature_c"],
	"type": "continuous",
	"min": 0.07407,
	"max": 9.579,
	"palette": ["#67001f", "#c94843", "#f6b69a", "#f2efee", "#a6cfe3", "#3a84bb", "#053061"],
}
difference_vis_params = {
	"bands": ["era5_minus_gfs_c"],
	"type": "continuous",
	"min": -5,
	"max": 5,
	"palette": ["#0d0887", "#7e03a8", "#cc4778", "#f89540", "#f0f921"],
}
images = daily.toList(len(dates))
era5_images = era5.toList(len(dates))
differences = []
for index, (timestamp, count) in enumerate(zip(dates, counts)):
	date = datetime.fromtimestamp(timestamp / 1000, tz=timezone.utc).strftime("%Y-%m-%d")
	image = ee.Image(images.get(index)).rename(["average_temperature_c", "minimum_temperature_c", "maximum_temperature_c"]).clip(france_geometry)
	realized = ee.Image(era5_images.get(index)).subtract(273.15).rename("average_temperature_c").clip(france_geometry)
	difference = realized.subtract(image.select("average_temperature_c")).rename("era5_minus_gfs_c").set("system:time_start", timestamp)
	differences.append(difference)
	Map.addLayer(
		image,
		vis_params,
		f"France GFS {date} | mean temperature (init 01 Nov 00 UTC)",
		shown=False,
		map_id=index + 1,
	)
	Map.addLayer(
		realized,
		vis_params,
		f"France ERA5-Land {date} | mean temperature",
		shown=False,
		map_id=index + 1,
	)
	Map.addLayer(
		difference,
		difference_vis_params,
		f"France ERA5-Land minus GFS {date} | mean temperature difference (°C)",
		shown=True,
		map_id=index + 1,
	)
	print(f"Map {index + 1}: {date}, {count} GFS forecast times; ERA5-Land minus GFS (°C)")

regions = ee.FeatureCollection("FAO/GAUL/2025/level1").filter(ee.Filter.eq("GAUL0_NAME", "France"))
fig, ax = plt.subplots(figsize=(12, 7))
ee.ImageCollection.fromImages(differences).geetools.plot_dates_by_regions(
	band="era5_minus_gfs_c",
	regions=regions,
	label="GAUL1_NAME",
	reducer="mean",
	scale=27830,
	colors=plt.get_cmap("turbo").resampled(regions.size().getInfo()).colors.tolist(),
	ax=ax,
)
ax.axhline(0, color="black", linewidth=0.8, alpha=0.5)
ax.set(title="Mean temperature error by French region (1–5 Nov 2026)", xlabel="Date", ylabel="Regional mean ERA5-Land − GFS (°C)")
ax.legend(title="Region", bbox_to_anchor=(1.02, 1), loc="upper left", fontsize="small")
fig.tight_layout()
fig.savefig(Path(__file__).resolve().parent / "france-regional-error.png", dpi=180, bbox_inches="tight")
